ALTER TABLE public.ReviewMedia ENABLE ROW LEVEL SECURITY;
CREATE POLICY Public can view non-private review media ON public.ReviewMedia AS PERMISSIVE FOR SELECT TO public USING ((EXISTS ( SELECT 1
   FROM "Reviews"
  WHERE (("Reviews".id = "ReviewMedia".review_id) AND ("Reviews".privacy_level <> 'private'::"Review Privacy Level")))));

-- Policy for table: ReviewMedia
ALTER TABLE public.ReviewMedia ENABLE ROW LEVEL SECURITY;
